INSERT INTO his.tb_goods (id, code, title, description, checkup_1, checkup_2, checkup_3, checkup_4, checkup, image, initial_price, current_price, sales_volume, type, tag, part_id, rule_id, status, md5, update_time, create_time) VALUES (1, '117GWMN00', '新感恩敬老中级体检套餐', '「感恩季到检钜惠」适合人群：适用于中、老年人及血管疾病人群 （参加第二件0元活动 需加入购物车后数量选2）', '[{"title": "一般健康检查", "content": "身高、体重、血压、心、肺、肝、脾、神经系统 ；甲状腺、乳腺、肛门、直肠"}]', '[{"title": "C反应蛋白", "content": "升高常见于：急性炎症、组织坏死、恶性肿瘤、风湿病等疾病"}, {"title": "肝功10项", "content": "丙氨酸氨基转移酶(ALT)测定 ；天门冬氨酸氨基转移酶(AST)测定；总蛋白(TP)测定 ；白蛋白(Alb)测定 ；碱性磷酸酶(ALP)测定 ;γ-谷氨酰基转移酶(GGT)测定;总胆红素(T-Bil)测定;直接胆红素(D-Bil)测定 ；总胆汁酸(TBA)测定 ；胆碱脂酶(ChE)测定"}, {"title": "甲功七项", "content": "三碘甲状腺原氨酸(T3)测定 ；甲状腺素(T4)测定 ；促甲状腺激素(TSH)测定 ；游离三碘甲状腺原氨酸(FT3)测定 ；游离甲状腺素(FT4)测定 ；抗甲状腺球蛋白抗体(TGAb)测定 ；抗甲状腺过氧化物酶抗体(TPOAb)测定"}, {"title": "尿常规", "content": "尿常规化学分析；尿有形成分分析"}, {"title": "肾功5项", "content": "尿素(Urea)测定 ；肌酐(Cr)测定 ；葡萄糖(Glu)测定 ；尿酸(UA)测定 ；β2微球蛋白(β2-MG)测定"}, {"title": " 糖化血红蛋白", "content": "检测近2-3个月内的平均血糖水平、用于糖尿病疗效观察"}, {"title": " 同型半胱氨酸", "content": "HCY升高是心血管疾病的重要危险因素"}, {"title": "肌红蛋白", "content": "肌红蛋白可作为急性心肌梗死(AMI) 诊断的早期最灵敏的指标"}, {"title": "肌钙蛋白", "content": "肌钙蛋白"}, {"title": "心肌酶谱", "content": "肌酸激酶(CK)测定 ；肌酸激酶-MB同工酶活性(CK-MB)测定 ；乳酸脱氢酶(LD)测定 ；α羟基丁酸脱氢酶(α-HBD)测定"}, {"title": "全血细胞分析", "content": "全血细胞分析（五分类），有无贫血、感染、凝血功能是否正常等"}, {"title": "血脂6项", "content": "血脂6项：总胆固醇(TC)测定 ；甘油三酯(TG)测定 ；高密度脂蛋白胆固醇(HDL-C)测定 ；低密度脂蛋白胆固醇(LDL-C)测定 ；载脂蛋白AⅠ(apoAⅠ)测定 ；载脂蛋白B(apoB)测定"}, {"title": "幽门螺杆菌抗体测定", "content": "细菌抗体测定"}, {"title": "恶性肿瘤特异性生长因子", "content": "筛查早期肿瘤"}]', '[{"title": "泌尿系彩色多普勒超声检查", "content": "双肾、肾盂、输尿管、膀胱壁、[前列腺（男）]"}, {"title": "肝胆胰脾彩色多普勒超声检查", "content": "肝胆胰脾彩色多普勒超声检查"}, {"title": "数字化摄影（指CR/DR)", "content": "心、肺、膈等"}, {"title": "超声骨密度检测", "content": "超声仪检查骨量情况，无骨质疏松、骨量减少"}, {"title": "心电图", "content": "检查心脏有否器官功能性病变，如：窦性心动过速、过缓、不齐以及各种心脏病的筛查"}]', '[{"title": "肿物标记物（男）", "content": " 男：甲胎蛋白(AFP)测定 ；癌胚抗原(CEA)测定 ;游离前列腺特异性抗原(FPSA)测定 ；总前列腺特异性抗原(TPSA)测定 ；糖类抗原CA-199测定"}]', '[{"sex": "无", "code": "无", "item": "裸眼视力(左)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "裸眼视力(右)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "裂隙灯检查", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "眼底检查", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "色觉检查", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "色盲#色弱#正常", "template": "模板1"}, {"sex": "无", "code": "无", "item": "身高", "name": "血压身高体重", "type": "录入", "place": "一般检查室", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "体重", "name": "血压身高体重", "type": "录入", "place": "一般检查室", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "血压", "name": "血压身高体重", "type": "录入", "place": "一般检查室", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "心肝脾肺", "name": "内科检查", "type": "录入", "place": "内科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "动脉硬化检测", "name": "动脉硬化检查", "type": "录入", "place": "动脉硬化检测室", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "淋巴结", "name": "外科检查", "type": "录入", "place": "外科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "甲状腺", "name": "外科检查", "type": "录入", "place": "外科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "脊柱四肢", "name": "外科检查", "type": "录入", "place": "外科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "鼻", "name": "耳鼻喉检查", "type": "录入", "place": "耳鼻喉科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "耳朵", "name": "耳鼻喉检查", "type": "录入", "place": "耳鼻喉科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "咽喉", "name": "耳鼻喉检查", "type": "录入", "place": "耳鼻喉科", "value": "未见异常#其他", "template": "模板1"}, {"se