INSERT INTO his.tb_goods (id, code, title, description, checkup_1, checkup_2, checkup_3, checkup_4, checkup, image, initial_price, current_price, sales_volume, type, tag, part_id, rule_id, status, md5, update_time, create_time) VALUES (3, '115GWMN00', '新亚健康高级体检套餐', '「感恩季到检钜惠」适用人群：青中年商务白领、职场人群、针对经常坐着上班的人群', '[{"title": "内科", "content": "身高、体重、BMI、血压、询问病史等"}, {"title": "外科", "content": "甲状腺、皮肤、淋巴结、乳腺、肛诊等"}, {"title": "眼科", "content": " 视力、外眼检查、色觉、裂隙灯检查、彩色眼底照相（不含胶片费）、非接触性眼压（进口机器）"}]', '[{"title": " 粪便常规（外观及镜检）", "content": "了解有无寄生虫病及肠道炎症"}, {"title": "便潜血检查", "content": " 早期发现消化道疾病，如溃疡、炎症、肿瘤等"}, {"title": " 红细胞沉降率（ESR）", "content": "炎症、结核、风湿活动期、心梗一周内、恶性肿瘤等均可升高"}, {"title": "肝功能11项", "content": "丙氨酸氨基转移酶（ALT）、天冬氨酸氨基转移酶（AST）、总蛋白定量（TP）、白蛋白定量（ALB）、球蛋白、球/白蛋白对比、总胆红素（TBIL 、直接胆红素（DBIL）、r-谷氨酰转肽酶（GGT）、碱性磷酸酶（ALP）、乳酸脱氢酶（LD）；了解蛋白质代谢、肝脏功能情况，是否有肝功能损害及损伤的程度、胆道梗阻及肝间质病变等"}, {"title": " 尿常规10项+尿沉渣（镜检）", "content": "了解尿路有无感染、结石等，了解有无尿蛋白、尿糖等"}, {"title": "肾功能及电解质", "content": " 尿酸（UA）、肌苷（CRE）、尿素氮（BUN）、血钠Na、血钾K、血氯CL、血钙Cａ、血磷P、血镁Mg、二氧化碳CO2；主要用于肾功能及电解质平衡的评价"}, {"title": "糖化血红蛋白（HbA1c）", "content": "了解近期血糖情况（1-3月的血糖平均值）,用于诊断糖尿病和评估血糖控制情况"}, {"title": "血糖（GLU）", "content": " 了解血糖情况"}, {"title": " 同型半胱氨酸（HCY）", "content": "对心脑血管疾病的危险度及预后进行评估"}, {"title": " 铁三项检测（Fe、TIBC、Fet）", "content": "括有血清铁 (Fe)、总铁结合力 (TIBC)、铁饱和度IS (Fe/TIBC) 、铁蛋白(Fet)。铁是人体的必需元素，具有生理活性的铁除以血浆的转铁蛋白形式存在外，主要以血红蛋白的形式存在，因此，缺铁会引起贫血。其明显增高或减低与急慢性炎症、血液系统、消化性系统、内分泌系统、免疫系统、肿瘤等疾病相关"}, {"title": "胃功能四项", "content": "G-17、PGⅠ、PGⅡ、PGⅠ/PGⅡ;用于反映胃体、胃窦粘膜的整体分泌状态"}, {"title": "全血细胞分析", "content": "了解有无感染、贫血、血液系统疾病等"}, {"title": "血脂7项", "content": "总胆固醇（CHO）、甘油三酯（TG）、高密度脂蛋白胆固醇 HDL-C、低密度脂蛋白胆固醇（LDL-C） 、小而密低密度脂蛋白胆固醇(sdLDL-C)、载脂蛋白A1(ApoA1)、载脂蛋白B（ApoB）；用于了解体内血脂情况，对动脉粥样硬化性疾病危险程度进行预测以及营养学评估"}, {"title": "碳-13呼气试验", "content": "检测胃内有无幽门螺旋杆菌感染，对反复慢性胃炎、溃疡、癌前病变有辅助诊治意义"}, {"title": "甲胎蛋白 (AFP)", "content": "主要用于肝癌早期筛查"}, {"title": "癌胚抗原(CEA)", "content": "主要用于肿瘤早期筛查"}]', '[{"title": " 泌尿系彩超（憋尿）", "content": "检查双肾及前列腺的大小、回声、有无结石及占位性病变，双侧输尿管有无扩张及占位性病变，膀胱壁及腔内情况"}, {"title": " 肝、胆、胰、脾（空腹）彩超", "content": "了解肝、胆、胰、脾各脏器的大小、结构是否正常，有无结石、炎症、肿物等病变"}, {"title": "颈动脉彩超", "content": "了解有无颈动脉硬化、斑块形成、管腔狭窄、痉挛等，评估动脉血管粥样硬化危险程度及辅助预测心脑血管疾病"}, {"title": "甲状腺彩超", "content": "了解甲状腺有无肿物、结节、肿大、炎症等"}, {"title": "动脉检测", "content": "肢体动脉检查+测量；了解肢体周围动脉硬化及血流情况，是评价动脉硬化程度的有效指标"}, {"title": "骨密度检查", "content": " 了解有无骨质减少、骨质疏松，预测骨折危险性"}, {"title": "DR胸部检查（不含胶片费）", "content": "了解双肺、心脏、纵隔情况"}, {"title": "人体成分检测", "content": "根据您目前的体重、体型、肌肉、骨骼等检测值评估个人身体状态，进行综合评价"}, {"title": "心电图（多导联）", "content": "通过了解心肌电活动，对冠心病及其他心脏病的诊断有提示作用，并可观察其转归，是诊断心律失常的基本手段"}]', '[{"title": " CTM-PEM检查", "content": "了解中医体质类型和心理健康程度"}]', '[{"sex": "无", "code": "无", "item": "裸眼视力(左)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "裸眼视力(右)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "裂隙灯检查", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "眼底检查", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "色觉检查", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "色盲#色弱#正常", "template": "模板1"}, {"sex": "无", "code": "无", "item": "身高", "name": "血压身高体重", "type": "录入", "place": "一般检查室", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "体重", "name": "血压身高体重", "type": "录入", "place": "一般检查室", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "血压", "name": "血压身高体重", "type": "录入", "place": "一般检查室", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "心肝脾肺", "name": "内科检查", "type": "录入", "place": "内科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "动脉硬化检测", "name": "动脉硬化检查", "type": "录入", "place": "动脉硬化检测室", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "淋巴结", "name": "外科检查", "type": "录入", "place": "外科", "value": "未见异常#其他", "t