INSERT INTO his.tb_goods (id, code, title, description, checkup_1, checkup_2, checkup_3, checkup_4, checkup, image, initial_price, current_price, sales_volume, type, tag, part_id, rule_id, status, md5, update_time, create_time) VALUES (4, '116GWMN00', '新感恩敬老高级体检套餐', '「感恩季到检钜惠」适合人群：适用于中、老年人及血管疾病人群 （参加第二件0元活动 需加入购物车后数量选2）', '[{"title": "内科查体", "content": "问诊（个人史、家族史、生活方式等）及一般状况、心肺、腹部、神经系统检查"}, {"title": "外科查体", "content": "皮肤、浅表淋巴结、头、颈部（甲状腺）、胸部（乳房）、脊柱、四肢关节、直肠指诊、男性外生殖器"}, {"title": "眼科", "content": "视功能检测、裂隙灯检查、小瞳孔眼底检查"}, {"title": "一般项目", "content": "身高、体重、BMI、血压、脉搏"}]', '[{"title": "便常规+潜血", "content": "用于对消化道疾病隐形出血如溃疡、肿瘤等检查"}, {"title": "离子组合", "content": "钙、磷、镁、铁"}, {"title": "电解质", "content": "钾、钠、氯、二氧化碳结合力"}, {"title": "乙肝五项", "content": "HBsAg、HBsAb、HBeAg、HBeAb、HBcAb"}, {"title": "丙肝抗体", "content": "检查是否有丙肝抗体"}, {"title": "甲功五项", "content": "FT3、FT4、T3、T4、TSH"}, {"title": "抗甲状腺自身抗体三项", "content": " ANTI-TG、ANTI-TPO、ANTR-TSHR"}, {"title": "尿液分析", "content": "尿常规10项+镜检"}, {"title": "凝血四项", "content": "反映血液的凝血功能及黏稠度"}, {"title": "尿肾功能", "content": " MALB、β2-MG、NAG更能主要反映肾脏的早期病变"}, {"title": "生化全项", "content": "生化检查内容包括肝功能、肾功能、血脂、血糖、心肌酶、电解质等"}, {"title": "糖化血红蛋白检测", "content": "监测血糖代谢，对糖尿病的早期诊断具有重要的意义，也是心脑血管疾病诊断及风险评估重要指标"}, {"title": "性激素六项", "content": " 促卵泡激素(FSH)/促黄体生成素(LH)/催乳素(PRL)/孕酮(PROG)/睾酮(TEST)/雌二醇(E2)"}, {"title": "血液分析", "content": "血常规23项（红细胞、白细胞、血小板系统）"}, {"title": "血型鉴定组合", "content": "ABO、RH(D)"}, {"title": "男肿标全项", "content": "FPSA、TPSA、FPSA/TPSA、NSE、CYFRA21-1（细胞角蛋白）、TG-M、AFP、CA125、CA19-9、CA72-4、CEA、Pro-CRP、SCC"}]', '[{"title": " 腹部彩超（肝、胆、脾、胰）", "content": "肝脏、胆囊、胰腺、脾脏的超声检查。"}, {"title": "男性泌尿系超声", "content": "双肾、双侧输尿管、膀胱、前列腺、双侧精囊腺"}, {"title": "颈动脉彩超", "content": " 人体中最早发生动脉硬化，也是硬化斑块危害最大，最严重的部位，可直接引起脑梗死，心梗等"}, {"title": "心脏彩超", "content": " 通过彩色超声检查心脏形态、结构及血流情况及功能，判定是否有各种先心病，心肌病，心瓣膜病，心包积液，心脏肿瘤等 "}, {"title": "甲状腺彩超", "content": "通过彩色超声仪检查甲状腺的形态、大小及血流情况、 判定是否有甲状腺肿大、结节、囊肿、肿瘤等 "}, {"title": "动脉硬化检测", "content": "肢体动脉检查+测量"}, {"title": "骨密度检测", "content": "判断骨质疏松、预测骨折风险,尤其适用于中老年人"}, {"title": "经颅多普勒", "content": " 大脑中动脉、椎动脉、基底动脉的血流速度"}, {"title": "肺部CT", "content": " 反映肺脏的形态，发现异常状态，如病灶大小，形态，部位，数目及其有无病灶内出血、坏死等。从病灶边沿情况可以了解其浸润性情况"}, {"title": "颈椎正侧斜位片", "content": "检查颈椎结构是否正常，有无异常病变"}, {"title": "腰椎正侧斜位片", "content": "可筛查腰椎有无骨质病变，关节关系是否正常，椎间孔大小有无异常，椎体有无异常等腰椎病变"}, {"title": "多导联心电图", "content": " 检测心脏电生理异常"}, {"title": "贫血三项", "content": "贫血的筛查"}]', '[{"title": "自身抗体五项", "content": "ANA、ANTI-AMA、ANTI-SMA、ANTI-PCA、ANTI-LKM"}, {"title": "胰岛功能两项", "content": "胰岛素、血清C肽"}, {"title": "糖化白蛋白", "content": "反映过去2-3周平均血糖水平的一项指标，在治疗效果的确认以及临床用药量的调整方面有重要指导作用"}, {"title": "心血管风险因子", "content": "检查是否存在心脑血管疾病"}, {"title": "C13幽门螺旋杆菌呼气检测", "content": "判断有无幽门螺杆菌的感染"}, {"title": "胃癌早期预警", "content": "胃蛋白酶原I（PGI）；胃蛋白酶原II（PGII）"}]', '[{"sex": "无", "code": "无", "item": "裸眼视力(左)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "裸眼视力(右)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "裂隙灯检查", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "眼底检查", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "色觉检查", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "色盲#色弱#正常", "template": "模板1"}, {"sex": "无", "code": "无", "item": "身高", "name": "血压身高体重", "type": "录入", "place": "一般检查室", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "体重", "name": "血压身高体重", "type": "录入", "place": "一般检查室", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "血压", "name": "血压身高体重", "type": "录入", "place": "一般检查室", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "心肝脾肺", "name": "内科检查", "type": "录入", "place": "内科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "动脉硬化检测", "name": "动脉硬化检查", "type": "录入", "place": "动脉硬化检测室", "v