INSERT INTO his.tb_goods (id, code, title, description, checkup_1, checkup_2, checkup_3, checkup_4, checkup, image, initial_price, current_price, sales_volume, type, tag, part_id, rule_id, status, md5, update_time, create_time) VALUES (7, '113GWMN00', '新精选女士体检套餐', '「感恩季到检钜惠」女性专项，重点关注妇科炎症、宫颈病变、乳腺疾病、卵巢', '[{"title": "耳鼻喉科", "content": "耳鼻喉科：耳、鼻、喉检查"}, {"title": "HPV病毒筛查", "content": " HPV病毒筛查"}, {"title": "宫颈防癌超薄涂片", "content": " 宫颈防癌超薄涂片"}, {"title": "妇科内诊", "content": "通过检查发现外阴皮肤有无异常；阴道有无出血、溃疡；宫颈有无充血和异常分泌物等；子宫有无异常；双侧附件有无肿块及压痛等"}, {"title": "内科", "content": "心、肺、肝、脾、神经系统检查"}, {"title": "肛门指诊", "content": "经肛门进行直肠癌筛查 "}, {"title": "外科", "content": "皮肤、浅表淋巴结、甲状腺、头颈、乳腺、脊柱、四肢、肛门、外生殖器、病史采集"}, {"title": "眼科", "content": "视力、辨色力、眼压、眼底照相、裂隙灯"}, {"title": "基本检查", "content": "身高体重血压检查极其比值，初步评定是否营养不良或营养过剩，检测是否有高血压以及低血压"}, {"title": "中医体检", "content": "中医体质辨识、中医经络辨识、中医健康调养咨询"}]', '[{"title": "大便常规+OB", "content": " 有无肠道感染、潜血 "}, {"title": "肝功能", "content": "肝功能（谷丙转氨酶、谷草转氨酶、谷氨酰转肽酶、总胆红素、直接胆红素、间接胆红素）"}, {"title": "甲状腺功能3项", "content": "是反应甲状腺功能状态的主要指标，用于甲状腺功能亢进或甲状腺功能减低等筛查"}, {"title": "尿常规+流式", "content": "有无泌尿系疾病、糖尿病、急慢性肾病"}, {"title": "肾功能", "content": "肾功能（肌酐、尿素氮、尿酸、β2-微球蛋白、血钙）"}, {"title": "血糖", "content": "血糖"}, {"title": "糖化血红蛋白检测", "content": "监测血糖代谢，对糖尿病的早期诊断具有重要的意义，也是心脑血管疾病诊断及风险评估重要指标"}, {"title": "同型半胱氨酸", "content": "冠脉硬化和心梗危险指标"}, {"title": "血常规", "content": "全血细胞分析，有无感染、贫血、凝血异常 "}, {"title": "血脂", "content": "血脂（总胆固醇、低密度脂蛋白胆固醇、高密度脂蛋白胆固醇、甘油三酯）"}, {"title": "幽门螺杆菌", "content": "经便探查幽门螺杆菌抗原"}, {"title": "防癌筛查女", "content": "癌胚抗原CEA、甲胎蛋白AFP、女性肿瘤：乳腺癌CA153、卵巢癌CA125"}]', '[{"title": "乳腺彩超", "content": "乳腺增生和结节情况"}, {"title": "腹部彩超", "content": "肝、胆、胰、脾彩超"}, {"title": "经腹部妇科彩超", "content": "经腹部妇科：子宫附件"}, {"title": "颈动脉+椎动脉彩超", "content": "颈部血管形态及斑块"}, {"title": "甲状腺彩超", "content": "甲状腺形态及血流改变"}, {"title": "泌尿系彩超", "content": "肾脏、膀胱、输尿管"}, {"title": "胸部正侧位", "content": "多方位检查心脏、两肺、纵隔、膈、胸膜，更好地发现和判断有无炎症、肿瘤等"}, {"title": "心电图", "content": "心脏电传导功能 "}]', null, '[{"sex": "无", "code"