INSERT INTO his.tb_goods (id, code, title, description, checkup_1, checkup_2, checkup_3, checkup_4, checkup, image, initial_price, current_price, sales_volume, type, tag, part_id, rule_id, status, md5, update_time, create_time) VALUES (8, '110GWMN00', '新孝心甄选体检套餐', '「感恩季到检钜惠」适合人群：适用于中、老年人及血管疾病人群【需加入购物车数量选2哦】', '[{"title": "内科", "content": "通过视、触、叩、听检查心、肺、肝、脾等重要脏器的基本状况，发现常见疾病的相关征兆，或初步排除常见疾病。"}, {"title": "口腔科", "content": "口腔常规检查，全面了解口腔健康状况，及时发现口腔科常见疾病"}, {"title": "外科", "content": "通过体格检查，检查皮肤、甲状腺、脊柱四肢、前列腺、外生殖器等重要脏器基本情况，发现常见外科疾病的相关征兆，或初步排除外科常见疾病"}, {"title": "妇科常规", "content": "通过妇科触诊及仪器检查方法，发现常见妇科疾病的相关征兆，或初步排除妇科常见疾病"}, {"title": "眼科检查", "content": "视力；辨色力；眼底检查；裂隙灯检查；眼压"}]', '[{"title": "白带常规", "content": "用于检查阴道内有无滴虫、念珠菌，同时还可确定阴道清洁度，是筛查阴道炎的有效手段"}, {"title": "宫颈超薄细胞检测（TCT）", "content": "即液基薄层细胞学检查。是筛查宫颈早期病变较先进的检测方法，同时还能发现部分癌前病变，微生物感染如霉菌、滴虫、病毒、衣原体、人乳头瘤病毒等"}, {"title": "肝功八项", "content": "了解肝脏功能情况的基本检查 。（谷丙转氨酶(ALT),谷草转氨酶(AST),总胆红素(TBIL),直接胆红素(DBIL),间接胆红素(IBIL),球蛋白(GLB),白蛋白(ALB),前白蛋白(PAB））"}, {"title": "甲状腺功能五项", "content": "了解甲状腺功能，辅助筛查有无甲亢、甲减等疾病"}, {"title": "尿常规", "content": "流式尿沉渣全自动分析加尿10项；筛查泌尿系感染及肾脏疾病"}, {"title": "肾功三项", "content": "尿素(UREA),肌酐(CREA),尿酸(URIC)了解肾脏功能情况"}, {"title": "糖化血红蛋白", "content": "了解2-3个月内血糖控制情况，辅助糖尿病早期筛查"}, {"title": "胃功能组合", "content": "胃蛋白酶原Ⅰ,胃蛋白酶原Ⅱ,人胃蛋白酶原I/II,胃泌素-17；协助诊断胃溃疡和萎缩，预测胃癌风险"}, {"title": "血常规", "content": "全血细胞五分类及网织红细胞；是筛查血液疾病和感染性疾病最基本的检查"}, {"title": "血脂六项", "content": "了解血脂，反应体内脂代谢情况，是评估心、脑血管风险因素的指标"}, {"title": "癌胚抗原", "content": "辅助筛查结肠癌、直肠癌、肺癌等"}, {"title": "甲胎蛋白", "content": "辅助筛查原发性肝癌"}]', '[{"title": "动脉硬化检测", "content": "检测四肢动脉硬化程度"}, {"title": "骨质疏松评估", "content": "25-羟基维生素D检测 、超声骨密度检查"}, {"title": "电脑多导联心电图", "content": "辅助筛查心脏类疾病"}, {"title": "前列腺超声", "content": "了解肾、输尿管、膀胱、前列腺结构病变(需要憋尿）"}, {"title": "甲状腺彩色多普勒超声扫描", "content": "了解甲状腺结构和病变"}, {"title": "双侧颈动脉彩色多普勒超声", "content": "了解中型动脉粥样硬化情况，预测冠脉粥样硬化风险"}]', null, '[{"sex": "无", "code": "无", "item": "裸眼视力(左)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无",