INSERT INTO his.tb_goods (id, code, title, description, checkup_1, checkup_2, checkup_3, checkup_4, checkup, image, initial_price, current_price, sales_volume, type, tag, part_id, rule_id, status, md5, update_time, create_time) VALUES (10, '101GWMN00', '熬夜党体检套餐', '熬夜党人群首选体检套餐【感恩季2022.12.20-2023.12.20期间到检享加赠或升级！】', '[{"title": "耳鼻喉科", "content": "耳、鼻、鼻窦、咽喉"}, {"title": "口腔科", "content": "齿、龈、唇、颊、腭、舌"}, {"title": "内科、外科", "content": "一般检查、测血压、中医体质辨识"}, {"title": "眼科", "content": "裂隙灯、外眼、眼底、眼压、视力、辨色力"}]', '[{"title": "肝功十项", "content": "可了解肝细胞有否损害，检查肝胆相关疾病等"}, {"title": "尿液分析", "content": "可提示有无泌尿系统疾患可能，如肾炎、肾盂肾炎、膀胱炎、尿道炎、泌尿系统结石、肾及膀胱肿瘤、糖尿病等"}, {"title": "肾功能3项", "content": "判断是否痛风及肾功能损害程度"}, {"title": "血糖", "content": "空腹血糖是最常用的检测指标，反应胰岛β细胞基础胰岛素的分泌功能。增高见于糖尿病、甲亢；降低见于饥饿、营养不良、糖代谢异常、严重肝病等"}, {"title": "血常规（18项）", "content": "判定是否有感染、贫血、血液疾病等"}, {"title": "血脂四项", "content": "检查有无高脂血症,评估动脉硬化和冠心病的重要指标"}, {"title": "幽门螺旋杆菌抗体检测", "content": "幽门螺旋杆菌(Hp)胃内感染, 1994年国际癌肿瘤研究机构和世界卫生组织将(Hp)列为第I类致癌因子"}, {"title": "T-PSA（男）", "content": "主要用于男性前列腺癌以及其它前列腺疾病的早期诊断"}]', '[{"title": "乳腺彩超（女）", "content": " 筛查乳腺小叶增生、肿瘤等"}, {"title": "妇科彩超（女）", "content": "妇科彩超"}, {"title": " 甲状腺彩超", "content": "甲状腺彩超"}, {"title": "肝、胆、胰、脾、双肾彩超", "content": "检查相应脏器大小、形态、结构、声像，了解有无各种良恶性病变，可筛查脂肪肝、结石、囊肿、肿瘤、血管瘤、肝硬化等病变，是腹部脏器必查的项目"}, {"title": "前列腺彩超（男）", "content": "彩色超声检查前列腺有无增生、肥大、囊肿、钙化等"}, {"title": "胸部彩超", "content": "检查心脏、两肺、纵隔、膈、胸膜，判断有无炎症、肿瘤等"}, {"title": "心电图", "content": "检查心脏有否器官功能性病变，如：窦性心动过速、过缓、不齐以及各种心脏病的筛查"}, {"title": "肿瘤2项", "content": "甲胎蛋白（AFP）：肝癌较有价值的辅助诊断指标。癌胚抗原（CEA）：存在远处转移的结直肠癌90％CEA增高，早期患者CEA升高者低于10％。胰腺、胃、肝、肺、乳腺、甲状腺、大肠及卵巢等恶性肿瘤时也可升高，CEA属广谱“肿瘤标志物”"}]', null, '[{"sex": "无", "code": "无", "item": "裸眼视力(左)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "裸眼视力(右)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "裂隙灯检查", "name": "眼科检查", "type": "录入", "place": "眼科", "value": 