INSERT INTO his.tb_goods (id, code, title, description, checkup_1, checkup_2, checkup_3, checkup_4, checkup, image, initial_price, current_price, sales_volume, type, tag, part_id, rule_id, status, md5, update_time, create_time) VALUES (11, '107GWMN00', '情侣体检套餐', '情人节专属特惠，两份仅2599元【感恩季2022.12.20-2023.4.20期间到检享加赠或升级！】', '[{"title": " 五官科检查", "content": "耳、鼻、鼻咽、喉、扁桃体检查等 "}, {"title": "内科", "content": " 心、肺听诊、腹部触诊等 "}, {"title": "外科", "content": "浅表淋巴结、甲状腺、乳房、脊柱、四肢、外生殖器、前列腺、肛指等 "}, {"title": "眼科", "content": "外眼、晶体、眼底检查等 "}, {"title": "一般检查", "content": "血压 "}, {"title": "阴道分泌物检查", "content": "白带清洁度及霉菌、滴虫感染检查"}]', '[{"title": "肝功能", "content": "谷丙转氨酶、胆红素测定，提示肝胆系统疾病"}, {"title": "甲状腺功能全套", "content": "诊断有无甲状腺机能亢进或甲状腺机能低下等疾病"}, {"title": "尿常规+沉渣", "content": "了解泌尿系统代谢功能、筛查肾炎、尿路感染、尿血、糖尿病等"}, {"title": " 肾功能", "content": "肌酐、尿素氮、尿酸、痛风等诊断指标 "}, {"title": "血糖", "content": "空腹血糖测定，了解是否有低血糖、糖尿病等疾病"}, {"title": "血同型半胱氨酸", "content": "血同型半胱氨酸测定，及早发现有无心梗、脑梗的危险因素"}, {"title": "血常规", "content": "白细胞计数、红细胞计数、血红蛋白含量、血小板等检测 "}, {"title": "血粘度", "content": "血液粘稠度测定，提示脑中风、高黏滞综合征等疾病"}, {"title": "血脂检测", "content": "甘油三酯、胆固醇测定，及早发现高血压、冠心病、脂肪肝、动脉硬化、胆结石等疾病，高、低密度脂蛋白测定，是监测血管硬化的重要指标"}, {"title": "尿核基质蛋白", "content": "尿核基质蛋白测定，及早发现有无膀胱癌的危险因素"}, {"title": "前列腺", "content": "前列腺：PSA、FPSA"}, {"title": "肺部肿瘤", "content": "肺部：CY211、NSE"}, {"title": "甲胎蛋白", "content": "AFP（甲胎蛋白）"}]', '[{"title": "甲状腺B超", "content": "了解甲状腺有无结节、肿大、肿块等"}, {"title": "腹部B超", "content": "肝、胆、胰、脾、肾疾病的诊断：如脂肪肝、肝囊肿、胆囊炎、胆石症、肾结石、肾囊肿等"}, {"title": "颈动脉B超", "content": "是诊断和评估颈动脉壁病变的有效手段，可检测早期动脉内膜有无粥样病变的存在"}, {"title": "头颅核磁共振", "content": "了解脑部有无病变，如脑血管疾病、脑肿瘤、脑出血、脑水肿等疾病"}, {"title": "骨密度", "content": "骨质密度测定，及早发现有无骨质疏松"}, {"title": "低剂量肺部CT平扫", "content": "低剂量肺部CT平扫"}, {"title": "心电图", "content": "心血管系统疾病的的诊断：如有无心律失常、心肌缺血、心肌病、冠心病等 "}, {"title": "消化道肿瘤", "content": "消化道：CEA、CA199、CA724、CA50、CA242"}, {"title": "乳腺彩超", "content": "筛查乳腺小叶增生、肿瘤等"}, {"title": "子宫、双附件彩超", "content": "通过彩色超声仪器更清晰地观察子宫及附件（卵巢、输卵管）大小、形态结构及内部回声的情况，鉴别正常和异常，了解病变的性质，判别有无恶性病变，以便尽早处置。"}]', null, '[{"sex": "无", "code": "无", "item": "裸眼视力(左)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "裸眼视力(右)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "裂隙灯检查", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "眼底检查", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "色觉检查", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "色盲#色弱#正常", "template": "模板1"}, {"sex": "无", "code": "无", "item": "身高", "name": "血压身高体重", "type": "录入", "place": "一般检查室", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "体重", "name": "血压身高体重", "type": "录入", "place": "一般检查室", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "血压", "name": "血压身高体重", "type": "录入", "place": "一般检查室", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "心肝脾肺", "name": "内科检查", "type": "录入", "place": "内科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "动脉硬化检测", "name": "动脉硬化检查", "type": "录入", "place": "动脉硬化检测室", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "淋巴结", "name": "外科检查", "type": "录入", "place": "外科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "甲状腺", "name": "外科检查", "type": "录入", "place": "外科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "脊柱四肢", "name": "外科检查", "type": "录入", "place": "外科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "鼻", "name": "耳鼻喉检查", "type": "录入", "place": "耳鼻喉科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "耳朵", "name": "耳鼻喉检查", "type": "录入", "place": "耳鼻喉科", "value": "未见异常#其他", "template": "模板1"}, {"sex": "无", "code": "无", "item": "咽喉", "name": "耳鼻喉检查", "type": "录