INSERT INTO his.tb_goods (id, code, title, description, checkup_1, checkup_2, checkup_3, checkup_4, checkup, image, initial_price, current_price, sales_volume, type, tag, part_id, rule_id, status, md5, update_time, create_time) VALUES (23, 'RWTHWWJ', '新精选男士体检套餐', '「感恩季到检钜惠」适合中青年人群、职场白领人士、针对经常坐着上班的人群', '[{"title": "耳鼻喉科", "content": "耳、鼻、鼻窦、咽喉"}, {"title": "口腔科", "content": " 齿、龈、唇、颊、腭、舌"}, {"title": "内科、外科", "content": " 内科、外科"}, {"title": "眼科", "content": "裂隙灯、外眼、眼底、眼压、视力、辨色力"}]', '[{"title": "风湿组合", "content": " C-反应蛋白、抗“O”、血沉、类风湿因子"}, {"title": "肝功十项", "content": "可了解肝细胞有否损害，检查肝胆相关疾病等"}, {"title": "甲功5项", "content": "甲功五项（TSH/T4/T3/FT4/FT3)"}, {"title": "尿液分析", "content": "可提示有无泌尿系统疾患可能，如肾炎、肾盂肾炎、膀胱炎、尿道炎、泌尿系统结石、肾及膀胱肿瘤、糖尿病等"}, {"title": "肾功能3项", "content": "判断是否痛风及肾功能损害程度"}, {"title": "血糖", "content": "空腹血糖是最常用的检测指标，反应胰岛β细胞基础胰岛素的分泌功能。增高见于糖尿病、甲亢；降低见于饥饿、营养不良、糖代谢异常、严重肝病等"}, {"title": "心肌酶4项", "content": "检查心脏功能，检查是否有心肌缺血或者是心肌坏死"}, {"title": "血常规", "content": "通过血液分析可发现有无贫血、细菌感染、病毒感染、白血病等系统疾病"}, {"title": "血脂四项", "content": "检查有无高脂血症,评估动脉硬化和冠心病的重要指标 "}, {"title": "幽门螺旋杆菌抗体检测", "content": "幽门螺旋杆菌(Hp)胃内感染, 1994年国际癌肿瘤研究机构和世界卫生组织将(Hp)列为第I类致癌因子"}, {"title": " 鳞状上皮细胞癌相关抗原", "content": "有助于鳞状上皮细胞起源癌的诊断和监测，如阴道癌、宫颈癌、肺癌、食管癌等"}, {"title": "糖类抗原CA-199", "content": "胰腺癌、胃癌、结直肠癌等辅助诊断。有些良性的病变例如胰腺炎等，也可能会导致糖类抗原199升高"}, {"title": "前列腺抗原2项", "content": "TPSA、FPSA"}]', '[{"title": "颈动脉彩超", "content": " 颈动脉彩超"}, {"title": " 甲状腺超声检查", "content": "是对甲状腺肿瘤的检查"}, {"title": " 肝、胆、胰、脾、双肾彩超", "content": " 检查相应脏器大小、形态、结构、声像，了解有无各种良恶性病变，可筛查脂肪肝、结石、囊肿、肿瘤、血管瘤、肝硬化等病变，是腹部脏器必查的项目"}, {"title": "前列腺彩超", "content": "彩色超声检查前列腺有无增生、肥大、囊肿、钙化等"}, {"title": "心电图", "content": "检查心脏有否器官功能性病变，如：窦性心动过速、过缓、不齐以及各种心脏病的筛查"}]', '[{"title": "肿瘤2项", "content": "甲胎蛋白（AFP）：肝癌较有价值的辅助诊断指标。癌胚抗原（CEA）：存在远处转移的结直肠癌90％CEA增高，早期患者CEA升高者低于10％。胰腺、胃、肝、肺、乳腺、甲状腺、大肠及卵巢等恶性肿瘤时也可升高，CEA属广谱“肿瘤标志物”"}]', '[{"sex": "无", "code": "无", "item": "裸眼视力(左)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无", "template": "模板1"}, {"sex": "无", "code"