INSERT INTO his.tb_goods (id, code, title, description, checkup_1, checkup_2, checkup_3, checkup_4, checkup, image, initial_price, current_price, sales_volume, type, tag, part_id, rule_id, status, md5, update_time, create_time) VALUES (26, 'ETYMTEK', '白领精英高级体检套餐', '适合白领精英人群，升级胸部CT，亚健康基础项目全面升级【感恩季2022.12.20-2023.12.20期间到检享加赠或升级！】', '[{"title": "耳鼻喉科", "content": "耳、鼻、喉、咽等有无异常"}, {"title": "内科", "content": "检查各种心脏病、心律失常及肺部疾病，炎症，肝脾有无肿大，肾病等"}, {"title": "外科", "content": "浅表淋巴结有无肿大，甲状腺、乳腺、前列腺、肛肠有无异常"}, {"title": "眼科", "content": "检查视力是否正常，有无屈光不正、色盲等"}, {"title": "一般检查", "content": "体重是否正常，有无体重不足、超重或肥胖，有无血压异常等"}]', '[{"title": "肝功能全套", "content": "全面评价肝胆代谢及解毒功能"}, {"title": "甲功3项", "content": "FT3+FT4+TSH 用于了解甲状腺功能状态"}, {"title": "尿沉渣", "content": "泌尿系统感染及肾脏疾病的初步筛查"}, {"title": "肾功能4项", "content": "尿素氮（BUN)、肌酐（CRE)、尿素氮/肌酐（BUN/CR）、尿酸(UA)"}, {"title": "空腹血糖", "content": "评价人体空腹状态下糖代谢是否正常，评估糖尿病患者空腹血糖控制是否达标。空腹血糖是诊断糖代谢紊乱的最常用和最重要指标"}, {"title": "血常规", "content": "通过血常规检查发现血液方面的问题，评价骨髓功能，有助于临床急慢性感染，病毒性疾病的判断；有助于了解有无贫血及贫血分类；有助于出血性疾病的诊断等"}, {"title": "血脂四项", "content": "检查有无高脂血症,评估动脉硬化和冠心病的重要指标"}, {"title": "幽门螺杆菌分型", "content": "幽门螺旋杆菌是1类致癌物，主要是判断机体是否存在该病菌的感染"}, {"title": "甲胎蛋白", "content": "原发性肝癌的重要指标"}, {"title": "糖链抗原CA199", "content": "筛查胰腺癌、胆囊癌、胃癌等肿瘤的辅助诊断"}, {"title": "糖链抗原", "content": "筛查胰腺癌和直结肠癌的肿瘤标志物。胃、结肠、肝、胰腺和胆管的非肿瘤性疾病时也有部分增高"}, {"title": "癌胚抗原", "content": "癌胚抗原CEA是空腔器官如胃肠道、呼吸道、泌尿道、乳腺、卵巢等的肿瘤标志物"}]', '[{"title": "乳腺彩超", "content": "筛查乳腺小叶增生、肿瘤等"}, {"title": "肝胆脾胰彩超", "content": "检查相应脏器大小、形态、结构、声像，了解有无各种良恶性病变，可筛查脂肪肝、结石、囊肿、肿瘤、血管瘤、肝硬化等病变，是腹部脏器必查的项目"}, {"title": "甲状腺彩超", "content": "通过彩色超声仪检查甲状腺的形态、大小及血流情况、 判定是否有甲状腺肿大、结节、囊肿、肿瘤等"}, {"title": "子宫、双附件彩超", "content": "通过彩色超声仪器更清晰地观察子宫及附件（卵巢、输卵管）大小、形态结构及内部回声的情况，鉴别正常和异常，了解病变的性质，判别有无恶性病变，以便尽早处置"}, {"title": "胸部CT", "content": "筛查肺部和纵膈肿瘤，以及气管、支气管、肺部疾病，评估心脏形态大小（备孕及怀孕期间暂禁检查） "}, {"title": "心电图", "content": "检查有无心律失常、缺血性心脏病、心肌病变等心脏缺血缺氧性疾病"}, {"title": "前列腺彩超", "content": "在膀胱充盈时通过彩色超声仪器检查。更清晰地观察前列腺大小、形态、结构等情况，判断有无前列腺增大、囊肿、结石，恶性病变等"}]',