INSERT INTO his.tb_goods (id, code, title, description, checkup_1, checkup_2, checkup_3, checkup_4, checkup, image, initial_price, current_price, sales_volume, type, tag, part_id, rule_id, status, md5, update_time, create_time) VALUES (27, 'ETYJEYTK', '婚前体检套餐', '婚前疾病筛查，本套餐仅出具体检报告，不出具婚前检查医学证明', '[{"title": "白带常规(女性项目)", "content": "对阴道分泌物检查，判断有无霉菌、滴虫感染及阴道炎"}, {"title": "妇科检查(女性项目)", "content": ") 了解外阴、阴道、宫颈、宫体、双侧附件等常见疾病和肿瘤"}, {"title": " 内科常规检查", "content": "通过对人体视、触、叩、听等物理方法，了解心、肺、肝、脾等内脏情，可筛查先心病、气管炎、及肝脾肿大等"}, {"title": "外科常规检查", "content": "常规皮肤、脊椎、四肢、甲状腺、乳房、浅表淋巴结等检查，发现外科病症与体征"}, {"title": "基础检查", "content": "身高、体重、体重指数、血压、心率是生命体征的基本信息，汇总分析身体健康状况的基础指标"}]', '[{"title": "肝功能三项", "content": "含谷草转氨酶、谷丙转氨酶、总胆红素三项检查，了解肝细胞新陈代谢，判断肝细胞损伤程度"}, {"title": "梅毒抗体检测", "content": "判断是否感染梅毒螺旋体"}, {"title": "艾滋病病毒检测", "content": "判断是否感染艾滋病病毒"}, {"title": "结核杆菌抗体", "content": "辅助诊断肺结核及其他部位结核"}, {"title": "丙肝抗体", "content": "作为HCV感染的标志，辅助诊断丙肝"}, {"title": "乙肝五项", "content": "是检查乙肝病毒及抗体的常用方法，辅助诊断乙型肝炎，指导乙肝疫苗的接种"}, {"title": "尿常规11项", "content": "检测尿液的成分、酸碱度、清洁度等，了解有无泌尿系感染，泌尿系肿瘤，急、慢性肾炎，糖尿病及其它全身性疾病等"}, {"title": "肾功能三项", "content": "含肾功二项、血尿酸，判断肾功能损害程度、有无痛风等"}, {"title": "空腹血糖", "content": "有无糖尿病及是否低血糖，筛检糖尿病最基本的方法"}, {"title": "血常规24项", "content": "检测血红蛋白、血细胞的数量和比例，了解有无贫血、感染及血液系统疾病"}, {"title": "血脂二项", "content": "含总胆固醇、甘油三酯，可判断高血脂症、肥胖综合症等"}]', '[{"title": " 盆腔彩超(女性项目)", "content": "检查子宫、附件、膀胱及周围组织，发现相关疾病及病变"}, {"title": "前列腺彩超(男性项目)", "content": "检查前列腺的炎性、囊性、增生、实性病变，发现有无良、恶性肿瘤"}, {"title": "腹部彩超", "content": "含肝、胆、胰、脾、双肾检查，诊断脂相关疾病及病变"}, {"title": "胸部透视", "content": "了解心脏、肺、胸膜、纵膈、膈肌、肋骨等发育及病理改变，及时发现炎症、结核、肿瘤等"}, {"title": "12导联心电图", "content": "描记心脏释放的生物电，了解心脏工作状态，是体检必查项目"}]', '[{"title": "红外线乳透(女性项目)", "content": "通过红外线透视，了解乳腺发育，对乳腺增生、肿块进行筛查"}]', '[{"sex": "无", "code": "无", "item": "裸眼视力(左)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无", "template": "模板1"}, {"sex": "无", "code": "无", "item": "裸眼视力(右)", "name": "眼科检查", "type": "录入", "place": "眼科", "value": "无", "template": "模板1"},