INSERT INTO his.tb_goods (id, code, title, description, checkup_1, checkup_2, checkup_3, checkup_4, checkup, image, initial_price, current_price, sales_volume, type, tag, part_id, rule_id, status, md5, update_time, create_time) VALUES (29, 'DFSHGFS', '新孝心父母体检套餐', '「感恩季到检钜惠」适合人群：适用于中、老年人及血管疾病人群【需加入购物车数量选2哦】', '[{"title": "内科", "content": "视诊、触诊、叩诊、听诊等物理诊断检查"}, {"title": "外科", "content": " 触摸淋巴结、甲状腺、脊柱、淋巴结发现临床疾病"}]', '[{"title": "大便潜血检查", "content": "排查肠道出血性疾病"}, {"title": "肝功4项", "content": "谷丙转氨酶 谷草转氨酶 碱性磷酸酶 谷氨酰转肽酶"}, {"title": "骨钙素-N肽", "content": "定量检测、特异性最高，反映了骨代谢现症情况"}, {"title": "淋巴细胞亚群", "content": "检测机体细胞免疫功能的重要指标，且对某些疾病(如自身免疫病、免疫缺陷病、恶性肿瘤、血液病、变态反应性疾病等)的辅助诊断"}, {"title": "尿常规", "content": "初步检查泌尿系统疾病"}, {"title": "肾功3项", "content": "尿素、肌酐、尿酸"}, {"title": "糖化血红蛋白检测", "content": "反映抽血前120天内的平均血糖水平，用于辅助诊断、评价治疗效果"}, {"title": "空腹血糖", "content": " 检查血糖，筛查糖尿病"}, {"title": "同型半胱氨酸", "content": "冠脉硬化和心梗危险指标"}, {"title": "血小板功能分析", "content": "脑梗、心梗等心脑血管疾病的高风险筛查手段"}, {"title": "血常规", "content": "检查血液系统各项常规指标"}, {"title": "血脂4项", "content": "甘油三酯 总胆固醇 高密度脂蛋白 低密度脂蛋白 检测体内血脂成分，血脂升高易患冠心病、动脉硬化等疾病"}, {"title": "甲胎蛋白", "content": "甲胎蛋白"}, {"title": "癌胚抗原", "content": "癌胚抗原"}, {"title": "前列腺特异性抗原（PSA）", "content": "前列腺特异性抗原（PSA）"}]', '[{"title": "彩超检查", "content": "甲状腺彩超 颈动脉彩超 肝脏、胆囊、胰腺、脾脏、肾脏、膀胱 前列腺彩超"}, {"title": "动脉硬化检测", "content": "诊断外周动脉是否存在粥样硬化及其严重程度"}, {"title": "骨密度", "content": "是骨骼强度的的重要指标"}, {"title": " 胸部平扫CT", "content": "发现肺部早期恶性肿瘤、肺部炎症"}, {"title": "人体成分分析", "content": "测定体脂肪含量、水含量、肌肉含量，指示身体健康状况"}, {"title": "12导心电图", "content": "初步筛查心律失常及心肌缺血"}, {"title": "眼底照相", "content": "检查视网膜（包括视乳头、黄斑、视网膜血管及除黄斑以外的视网膜）"}, {"title": "乳腺超声", "content": "乳腺超声"}, {"title": "子宫附件超声", "content": "子宫附件超声"}]', '[{"title": "脂蛋白相关磷脂酶A2", "content": "是血管炎症反应的特异性标志物，能动态反映动脉粥样硬化的严重程度，对预防心脑血管突发事件具有重要意义。检测结果升高标明动脉硬化斑块不稳定容易破裂，可能会诱发严重的心脑血管疾病。用于心脑血管疾病风险的早期预测"}, {"title": "膀胱肿瘤抗原检测", "content": "膀胱泌尿系统肿瘤筛查"}]', '[{"sex": "无", "code": "无", "item": "裸眼视力(左)", "name": "眼科检查", "type": "录入", "place"