INSERT INTO his.tb_rule (id, name, rule, remark) VALUES (1, '两件五折', 'result = (number.intValue() / 2) * (price * 0.5 + price * 0.5) + (number.intValue() % 2) * price', '每购买两个相同套餐，两个套餐都享受半价');
